function validate([queries]) {
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 150000) return 'queries needs 1 to 15 * 10^4 entries.';
  const bound = Math.min(50000, 3 * queries.length);
  const built = new Set();
  let asks = 0;
  for (const query of queries) {
    if (!Array.isArray(query) || !(query[0] === 1 && query.length === 2 || query[0] === 2 && query.length === 3)) return 'Each query is [1, x] or [2, x, sz].';
    if (query.slice(1).some(v => !Number.isInteger(v) || v < 1 || v > bound)) return 'x and sz are between 1 and min(5 * 10^4, 3 * queries.length).';
    if (query[0] === 2) asks++;
    else if (built.has(query[1])) return 'Two obstacles cannot be built at the same x.';
    else built.add(query[1]);
  }
  if (asks === 0) return 'At least one query must have type 2.';
  return null;
}

