function getResults(queries) {
  const limit = queries.reduce((most, query) => Math.max(most, query[1]), 0);
  const first = new Array(4 * (limit + 1)).fill(-1);
  const last = new Array(4 * (limit + 1)).fill(-1);
  const gap = new Array(4 * (limit + 1)).fill(0);

  const update = (node, lo, hi, pos) => {
    if (lo === hi) {
      first[node] = pos;
      last[node] = pos;
      return;
    }
    const mid = (lo + hi) >> 1;
    const left = 2 * node;
    const right = 2 * node + 1;
    if (pos <= mid) {
      update(left, lo, mid, pos);
    } else {
      update(right, mid + 1, hi, pos);
    }
    first[node] = first[left] !== -1 ? first[left] : first[right];
    last[node] = last[right] !== -1 ? last[right] : last[left];
    gap[node] = Math.max(gap[left], gap[right]);
    if (last[left] !== -1 && first[right] !== -1) {
      gap[node] = Math.max(gap[node], first[right] - last[left]);
    }
  };

  let prev = 0;
  let best = 0;
  const scan = (node, lo, hi, x) => {
    if (lo > x || first[node] === -1) {
      return;
    }
    if (hi <= x) {
      best = Math.max(best, gap[node], first[node] - prev);
      prev = last[node];
      return;
    }
    const mid = (lo + hi) >> 1;
    scan(2 * node, lo, mid, x);
    scan(2 * node + 1, mid + 1, hi, x);
  };

  const results = [];
  for (const [type, x, sz] of queries) {
    if (type === 1) {
      update(1, 0, limit, x);
    } else {
      prev = 0;
      best = 0;
      scan(1, 0, limit, x);
      results.push(Math.max(best, x - prev) >= sz);
    }
  }
  return results;
}

