function getResults(queries) {
  const obstacles = [];
  const results = [];
  for (const query of queries) {
    if (query[0] === 1) {
      obstacles.push(query[1]);
      continue;
    }
    const [, x, sz] = query;
    // Obstacles sit on whole numbers, so a block that fits can slide left until its start is a whole number too.
    let fits = false;
    for (let start = 0; start + sz <= x; start++) {
      if (!obstacles.some(p => start < p && p < start + sz)) fits = true;
    }
    results.push(fits);
  }
  return results;
}

