function generate(rand, size) {
  const count = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const bound = Math.min(50000, 3 * count);
  const share = 0.15 + 0.7 * rand();
  const taken = new Set();
  const walls = [];
  const queries = [];
  let asked = false;
  for (let i = 0; i < count; i++) {
    // The last query must ask if none has yet, since at least one type-2 query is guaranteed.
    if (rand() < share && (asked || i < count - 1)) {
      let x = 1 + Math.floor(rand() * bound);
      while (taken.has(x)) x = 1 + Math.floor(rand() * bound);
      taken.add(x);
      let lo = 0, hi = walls.length;
      while (lo < hi) { const mid = (lo + hi) >> 1; if (walls[mid] < x) lo = mid + 1; else hi = mid; }
      walls.splice(lo, 0, x);
      queries.push([1, x]);
      continue;
    }
    const x = 1 + Math.floor(rand() * bound);
    // Aim sz near the widest free piece of [0, x] so that both answers show up.
    let widest = 0, prev = 0;
    for (const wall of walls) {
      if (wall > x) break;
      widest = Math.max(widest, wall - prev);
      prev = wall;
    }
    widest = Math.max(widest, x - prev);
    const sz = rand() < 0.2 ? 1 + Math.floor(rand() * bound) : Math.min(bound, Math.max(1, widest + Math.floor(rand() * 5) - 2));
    queries.push([2, x, sz]);
    asked = true;
  }
  return [queries];
}
